JS = '''
(()=>{const badge=document.getElementById('workspace-profile-badge');function apply(profile){if(!badge)return;const name=String(profile.display_name||'Brain');badge.textContent=Array.from(name)[0].toUpperCase();badge.title=name;badge.setAttribute('aria-label','设置：'+name);const avatar=String(profile.avatar_url||'');if(avatar&&(avatar.startsWith('https://')||avatar.startsWith('http://')||avatar.startsWith('/')&&!avatar.startsWith('//'))){const image=document.createElement('img');image.src=avatar;image.alt='';image.referrerPolicy='no-referrer';image.addEventListener('error',()=>{badge.textContent=Array.from(name)[0].toUpperCase()},{once:true});badge.replaceChildren(image)}let saved;try{saved=localStorage.getItem('hermes_theme')}catch(_){}if(!saved&&profile.theme==='modern-dark'){document.documentElement.dataset.theme='dark';document.dispatchEvent(new Event('brain-theme-change'))}}document.addEventListener('brain-profile-change',event=>apply(event.detail));fetch('/api/settings/profile',{credentials:'same-origin'}).then(response=>response.ok?response.json():null).then(profile=>{if(profile)apply(profile)}).catch(()=>{})})();
(()=>{const root=document.documentElement;let saved;try{saved=localStorage.getItem('hermes_theme')}catch(_){}if(saved==='dark'||saved==='modern-dark')root.dataset.theme='dark';document.getElementById('theme-toggle')?.addEventListener('click',()=>{const next=root.dataset.theme==='dark'?'light':'dark';root.dataset.theme=next;try{localStorage.setItem('hermes_theme',next)}catch(_){}document.dispatchEvent(new Event('brain-theme-change'));});const menu=document.getElementById('mobile-menu');const close=()=>{document.body.classList.remove('nav-open');menu?.setAttribute('aria-expanded','false')};menu?.addEventListener('click',()=>{const open=document.body.classList.toggle('nav-open');menu.setAttribute('aria-expanded',String(open))});document.getElementById('nav-overlay')?.addEventListener('click',close);document.addEventListener('keydown',event=>{if(event.key==='Escape')close();if(event.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){event.preventDefault();document.querySelector('input[type=search]')?.focus()}});document.querySelectorAll('[data-decision]').forEach(button=>button.addEventListener('click',async()=>{const message=document.getElementById('decision-status');if(!window.confirm(button.dataset.confirm))return;button.disabled=true;try{const response=await fetch(button.dataset.decision,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:'{}'});if(!response.ok)throw new Error('操作未保存，请重试。');message.textContent='已保存';window.location.assign('/proposals')}catch(error){message.textContent=error.message;button.disabled=false}}));})();
'''


def shell(title: str, body: str, *, active: str = "home", pending: int | None = None, extra_js: str = "") -> str:
    nav = []
    for key, path, label, symbol in [("home", "/", "概览", "home"), ("knowledge", "/knowledge", "经验库", "book"), ("proposals", "/proposals", "待整理", "inbox"), ("projects", "/projects", "工作记录", "activity")]:
        badge = f'<span class="nav-count">{pending}</span>' if key == "proposals" and pending else ""
        nav.append(f'<a href="{path}" class="{"active" if active == key else ""}" {"aria-current=page" if active == key else ""}>{icon(symbol)}<span>{label}</span>{badge}</a>')
    utilities = ''.join(f'<a href="{path}" class="{"active" if active == key else ""}" {"aria-current=page" if active == key else ""}>{icon(symbol,18)}{label}</a>' for key,path,label,symbol in [("environments","/environments","服务器与目录","globe"),("gallery","/gallery","图表模板","layers"),("settings","/settings","设置","settings")])
    return f'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#f7f8fc"><title>{e(title)} · Brain</title><style>{CSS}</style></head><body>
<a class="skip" href="#main-content">跳到主要内容</a><div class="mobile-overlay" id="nav-overlay"></div>
<aside class="sidebar" aria-label="主导航"><a href="/" class="brand"><span class="brand-mark">b</span>Brain</a><div class="workspace-picker">{icon('layers')}<div><strong>共享经验</strong><small>从工作中积累，供下次使用</small></div></div><div class="nav-label">工作空间</div><nav class="nav">{''.join(nav)}</nav><div class="sidebar-bottom">{utilities}<button id="theme-toggle" type="button">{icon('sun',18)}切换明暗</button><small>Brain · 共享经验工作空间</small></div></aside>
<div class="app"><header class="topbar"><div class="breadcrumb"><button class="mobile-menu" id="mobile-menu" aria-label="展开导航" aria-expanded="false">{icon('menu')}</button><span>工作空间</span><span>/</span><strong>{e(title)}</strong></div><div class="topbar-right"><span>经验有来源，审阅有记录</span><a class="profile-dot" id="workspace-profile-badge" href="/settings" aria-label="设置">B</a></div></header><main class="main" id="main-content">{body}</main></div><script>{JS}
{extra_js}</script></body></html>'''


def review_badge(note: dict | None, *, outdated: bool = False) -> str:
    if not note:
        return f'<span class="tag amber">{"内容已变，待复审" if outdated else "尚无初审记录"}</span>'
    disposition = note["disposition"]
    tone = "green" if disposition in {"retain", "scope"} else "red" if disposition == "conflict" else "amber" if disposition == "verify" else "purple"
    return f'<span class="tag {tone}">{e(DISPOSITIONS.get(disposition, disposition))}</span>'


def title_for(item: dict) -> str:
    note = item.get("editorial_review")
    return str(note["title_zh"] if note else item.get("summary") or item.get("lesson") or "未命名内容")


def description_for(item: dict) -> str:
    note = item.get("editorial_review")
    return str(note["summary_zh"] if note else item.get("content") or item.get("suggested_memory") or item.get("summary") or "")


def knowledge_rows(nodes: list[dict]) -> str:
    rows = []
    for node in nodes:
        stage = str(node.get("stage") or "draft")
        stage_label = {"draft": "草稿", "refined": "已整理", "verified": "已核实", "canonized": "已入库", "deprecated": "已停用"}.get(stage, stage)
        topic = {"science": "研究分析", "tech": "开发运维", "research": "研究分析", "general": "通用经验", "presentation-engineering": "科研汇报"}.get(str(node.get("domain") or ""), str(node.get("domain") or "通用经验"))
        url = '/knowledge/' + quote(str(node.get('id') or ''), safe='')
        rows.append(f'''<a class="record" href="{e(url)}"><div class="record-copy"><strong class="record-title">{e(title_for(node))}</strong><span class="record-desc">{e(description_for(node)[:200])}</span><div class="record-meta"><span>{e(topic)}</span>{'<span>已有中文导读</span>' if node.get('editorial_review') else ''}</div></div><div><span class="tag {'green' if stage in {'verified','canonized'} else ''}">{e(stage_label)}</span></div><span class="record-date">{e(str(node.get('created_at') or '')[:10])}</span></a>''')
    return ''.join(rows) or '<div class="empty"><strong>这里还没有经验</strong><p>调整检索条件，或等新的工作经验整理入库。</p></div>'


def home(*, nodes: list[dict], counts: dict, pending: int, reviewed: int, topic_counts: dict, activity: dict | None = None) -> str:
    active = sum(int(value) for stage, value in counts.items() if stage != 'deprecated')
    cards = []
    for topic, label, text, symbol in [("science", "研究与分析", "统计方法、实验流程与结果解读", "flask"), ("tech", "开发与运维", "运行环境、工具使用与故障处理", "code"), ("general", "协作与习惯", "工作约定、表达方式与可复用经验", "globe")]:
        cards.append(f'<a class="collection" href="/knowledge?topic={topic}"><span class="collection-icon">{icon(symbol)}</span><h3>{label}</h3><p>{text}</p><div class="collection-bottom"><span>{int(topic_counts.get(topic,0))} 条经验</span>{icon("arrow",16)}</div></a>')
    review_line = f'{reviewed} 条已完成内容初审' if reviewed else '旧内容正在重新整理'
    body = f'''<section class="hero"><p class="eyebrow">共享经验</p><h1>把经验用起来。</h1><p>找到上次解决问题的方法，让下一次工作少走一点弯路。</p><form class="search" action="/knowledge" method="get" role="search">{icon('search',19)}<input type="search" name="q" placeholder="搜索经验，例如：Python 环境、绘图规范、任务调度" aria-label="搜索经验"><button type="submit">搜索</button></form><div class="hero-links"><span><strong>{active}</strong> 条在用经验</span><span><strong>{pending}</strong> 条待整理</span><span>原始记录和来源始终保留</span></div></section><section aria-label="经验分类"><div class="section-head"><h2>按主题找经验</h2><a class="text-link" href="/knowledge">浏览全部 {icon('arrow',14)}</a></div><div class="collections">{''.join(cards)}</div></section><section class="callout">{icon('inbox',22)}<div class="copy"><strong>历史内容，先整理清楚再决定</strong><p>{review_line}。查看中文摘要、审阅意见和建议去向。</p></div><a href="/proposals">查看待整理 →</a></section><section><div class="section-head"><h2>经验库一览</h2><a class="text-link" href="/knowledge">查看全部 {icon('arrow',14)}</a></div><div class="list"><div class="list-head"><span>经验</span><span>状态</span><span>记录日期</span></div>{knowledge_rows(nodes[:5])}</div></section><p class="footer-note">工作记录保存发生过什么；经验库保存下次还能用的方法。待整理内容经过审阅后再决定是否入库。</p>'''
    return shell('概览', body, pending=pending)


def knowledge_index(*, nodes: list[dict], counts: dict, query: str = '', topic: str = '', stage: str = 'active', page: int = 1) -> str:
    total = len(nodes)
    size = 20
    pages = max(1, (total + size - 1) // size)
    page = min(max(1, page), pages)
    def url(**values):
        return '/knowledge?' + urlencode({'q':query,'topic':topic,'stage':stage, **values})
    pills = ''.join(f'<a class="pill {"active" if key==topic else ""}" href="{e(url(topic=key,page=1))}">{label}</a>' for key,label in [('', '全部经验'),('science','研究与分析'),('tech','开发与运维'),('general','协作与习惯')])
    options = ''.join(f'<option value="{key}" {"selected" if key==stage else ""}>{label}</option>' for key,label in [('active','在用经验'),('all','包含停用'),('draft','草稿'),('refined','已整理'),('verified','已核实'),('canonized','已入库'),('deprecated','已停用')])
    body = f'''<header class="page-head"><div><p class="eyebrow">经验库</p><h1>经验库</h1><p>按问题找方法，也能追溯每条经验的来源。</p></div><a class="btn" href="/knowledge?view=graph">{icon('layers',16)}关系图</a></header><form class="filters" method="get" action="/knowledge"><div class="search">{icon('search',18)}<input type="search" name="q" value="{e(query)}" aria-label="搜索经验" placeholder="搜索标题、中文导读或原文"><button>搜索</button></div><input type="hidden" name="topic" value="{e(topic)}"><select name="stage" aria-label="经验状态" onchange="this.form.submit()">{options}</select></form><nav class="pills" aria-label="按主题筛选">{pills}</nav><div class="section-head"><h2>{total} 条经验</h2><span class="muted">{f'第 {page} / {pages} 页' if pages>1 else '已停用的经验默认收起'}</span></div><div class="list"><div class="list-head"><span>经验</span><span>状态</span><span>记录日期</span></div>{knowledge_rows(nodes[(page-1)*size:page*size])}</div><div class="pagination"><span>显示 {(page-1)*size+1 if total else 0}–{min(page*size,total)} / {total}</span><div>{f'<a class="btn" href="{e(url(page=page-1))}">上一页</a>' if page>1 else ''} {f'<a class="btn" href="{e(url(page=page+1))}">下一页</a>' if page<pages else ''}</div></div>'''
    return shell('经验库', body, active='knowledge')


def proposal_detail(*, proposal: dict, environment: dict | None = None) -> str:
    note=proposal.get('editorial_review');pid=str(proposal['proposal_id']);safe_id=quote(pid,safe='');state=str(proposal.get('state'))
    title=title_for(proposal)
    if note:
        review=f'''<section class="panel"><div class="panel-title"><h2>Agent 的初审意见</h2>{review_badge(note)}</div><div class="review-by"><span class="profile-dot">C</span><div><strong>{e(note['reviewer'])}</strong><small>{e(note['reviewed_at'][:16].replace('T',' '))} UTC · 阅读提交内容后形成意见</small></div></div><p>{e(note['reasoning'])}</p><div class="review-step"><span>下一步怎么做</span><p>{e(note['next_step'])}</p></div><p class="subtle-note">核验范围：已读提交的说明和证据摘录；未重新执行历史任务，也未核实远端原始文件。</p></section>'''
    else:
        review=f'<section class="panel"><h2>{"内容已变，原初审意见需要更新" if proposal.get("review_outdated") else "这条内容还没有初审记录"}</h2><p class="muted">提交者 {e(proposal.get("source_agent"))} 负责记录经验；页面只在存在具名、匹配当前内容的审阅记录时显示“已初审”。</p></section>'
    sections=''.join(f'<details><summary>{label}<small>查看原始内容</small></summary><pre class="raw">{e(proposal.get(key) or "未提供")}</pre></details>' for label,key in [('原始提案','summary'),('发生了什么','observation'),('为什么值得记住','why_it_matters'),('建议写入的经验','suggested_memory'),('适用范围','scope'),('证据与出处','evidence')])
    env=environment or {};scope=' / '.join(str(env.get(k) or '') for k in ['server_id','user_root','project_root'] if env.get(k)) or str(proposal.get('scope') or '未标明')
    states={'pending':'尚未入库','approved_db_only':'已存入记忆库','approved_for_export':'已批准同步','rejected':'已拒绝','superseded':'已被替代'}
    actions=''
    if state in {'pending','approved_db_only'}:
        if state=='pending':actions+=f'<button class="btn primary" data-decision="/api/review/{e(safe_id)}/approve-db-only" data-confirm="批准这条提案仅保存在 Brain 中？">存入记忆库</button>'
        actions+=f'<button class="btn" data-decision="/api/review/{e(safe_id)}/reject" data-confirm="拒绝这条提案？原始内容和初审记录会保留。">拒绝此条</button>'
        actions+=f'<details><summary>同步到 Agent</summary><p class="muted">批准后，这条经验会进入 Agent 可读取的导出内容。</p><button class="btn" data-decision="/api/review/{e(safe_id)}/approve-for-export" data-confirm="批准并同步这条经验到 Agent？">批准并同步</button></details>'

    from .workspace_relations import relationship_section
    relationships = relationship_section(proposal)
    body=f'''<a class="text-link" href="/proposals">← 回到待整理</a><header style="margin-top:20px"><h1 class="detail-title">{e(title)}</h1><div class="detail-meta"><span>{e(states.get(state,state))}</span><span>提交者 {e(proposal.get('source_agent'))}</span><span>{e(str(proposal.get('created_at') or '')[:10])}</span></div></header><div class="detail-grid"><div><section class="panel"><h2>这条经验讲什么</h2><p>{e(description_for(proposal))}</p></section>{review}{relationships}{sections}<a class="text-link" href="/review/{e(safe_id)}?view=raw">编辑结构化原文 →</a></div><aside class="detail-aside"><section class="panel"><h3>来源与适用范围</h3><dl><dt>提交者</dt><dd>{e(proposal.get('source_agent'))}</dd><dt>内容初审者</dt><dd>{e(note['reviewer'] if note else '暂无记录')}</dd><dt>适用范围</dt><dd>{e(scope)}</dd><dt>来源主机</dt><dd>{e(proposal.get('source_host'))}</dd><dt>提案编号</dt><dd>{e(pid)}</dd></dl></section><section class="panel detail-actions"><h3>决定是否留下</h3><p class="muted">先阅读初审意见和证据，再决定是否入库。入库与同步到 Agent 是不同操作。</p>{actions}<p id="decision-status" class="status-message" role="status"></p></section></aside></div>'''
    return shell('待整理详情',body,active='proposals')


def knowledge_detail(*, node: dict, conflicts: list[dict] | None = None, exploration: dict | None = None) -> str:
    from .knowledge_exploration import exploration_sections
    visuals = exploration_sections(exploration) if exploration else ""
    note=node.get('editorial_review')
    from .workspace_relations import relationship_section
    relationships = relationship_section(node)
    conflict_html = ''
    if conflicts:
        links = ''.join(f'<a class="text-link" href="/knowledge/{e(quote(str(item["id"]),safe=""))}">{e(title_for(item))} →</a>' for item in conflicts)
        conflict_html = f'<section class="panel"><h2>有冲突的关联经验</h2><p class="muted">原始记录标记了冲突，使用前请核对适用范围和证据。</p>{links}</section>'
    body=f'''<a class="text-link" href="/knowledge">← 回到经验库</a><header style="margin-top:20px"><h1 class="detail-title">{e(title_for(node))}</h1><div class="detail-meta"><span>经验库</span><span>{e(node.get('domain') or '通用经验')}</span><span>{e(str(node.get('created_at') or '')[:10])}</span></div></header>{visuals}<div class="detail-grid" id="knowledge-content"><div>{relationships}{conflict_html}{f'<section class="panel"><h2>中文导读</h2><p>{e(note["summary_zh"])}</p></section>' if note else ''}<section class="panel"><h2>经验原文</h2><pre class="raw" style="color:var(--ink);margin-top:0">{e(node.get('content'))}</pre></section><details><summary>证据与出处</summary><pre class="raw">{e(node.get('evidence') or '未提供')}</pre></details><a class="text-link" href="/knowledge/{e(quote(str(node['id']),safe=''))}?view=raw">查看高级关系、处理记录和使用反馈 →</a></div><aside class="detail-aside"><section class="panel"><h3>记录信息</h3><dl><dt>来源</dt><dd>{e(node.get('source'))}</dd><dt>检索返回计数</dt><dd>{e(node.get('retrieval_count',0))}</dd><dt>内容整理</dt><dd>{e(note['reviewer'] if note else '尚无中文导读')}</dd><dt>说明</dt><dd>历史入库状态不代表已经独立核实；证据以原始记录为准。</dd></dl></section></aside></div>'''
    return shell('经验详情',body,active='knowledge')
